The expected (total) regret for algorithm \textbf{algo} over $K$ episodes of interaction with the MDP $\mathcal{M}$ is then defined as 
\begin{equation}\label{eq:regret}
Regret(\mathcal{M},\textbf{algo},K)=E\left [\sum_{k=1}^K(V_1^*(s_1^k)-V_1^{\pi^k}(s_1^k))\right ],
\end{equation}
where the term $V_1^*(s_1^k)-V_1^{\pi^k}(s_1^k)$ measures the performance loss when the agent executes (suboptimal) policy $\pi^k$ in episode $k$.

   \caption{The OCE-VI Algorithm}
   \label{ALG}
\begin{algorithmic}
   \STATE {\bfseries Input:} Parameters $\delta,\mathcal{S},\mathcal{A},H,K,r$ and an utility function $u \in U_0$
   \STATE Initialize $\hat{V}_{h}(s)\gets 0$, $N_h(s,a,s')\gets 0$ and $N_h(s,a)\gets 0$ for all $(s,a,h)\in\mathcal{S}\times\mathcal{A}\times [H+1]$.
   \FOR{episode $k=1,\cdots ,K$}
   \FOR{step $h=H,H-1,\cdots,1$}
   \FOR{$(s,a)\in \mathcal{S}\times \mathcal{A}$}
   \IF{$N_h(s,a)\geq 1$}
   \STATE Update $b_h(s,a)$ by \eqref{S11} according to the utility function $u$
   \STATE$\hat{Q}_h(s,a)\gets \min{\{r_h(s,a)+OCE^{u}_{s'\sim \hat{P}_h(\cdot\vert s,a)}(\hat{V}_{h+1}(s'))+b_h(s,a),H-h+1\}}$
   \STATE $\hat{V}_h(s)\gets \max_{a'\in \mathcal{A}}\hat{Q}_h(s,a')$
   \ELSE
   \STATE $\hat{Q}_h(s,a)\gets H-h+1$
   \ENDIF
   \ENDFOR
   \ENDFOR
   \STATE For all $h\in [H]$, take $\pi^k_h(s_h)\gets argmax_{a'\in \mathcal{A}}\hat{Q}_h(s_h,a')$
   \STATE Play the episode $k$ with policy $\pi^k$, update $N_h(s,a),N_h(s,a,s')$ and $\hat{P}_h(s'\vert s,a)$ for all $h\in [H]$
   \ENDFOR
\end{algorithmic}

\label{THM1}
The expected regret of the OCE-VI algorithm satisfies
\begin{align*}
&Regret(\mathcal{M},\textbf{OCE-VI},K)\leq \tilde{\mathcal{O}}\left(\sum_{h=1}^H\vert u(-H+h)\vert S\sqrt{\prod\limits_{i=1}^{h-1} u_{-}'(-H+i)AK}\right),
\end{align*}
where 
$\tilde{\mathcal{O}}(\cdot)$ ignores the logarithmic factors in $S,A,H$ and $K$ and $u'_{-}(\cdot)$ is the left derivative of $u$.

\label{THM3}
Under Assumption \ref{ASSU2}, for any algorithm \textbf{algo}, there exists an MDP $\mathcal{M}$ whose transition probabilities depend on $h$ such that
\begin{align*}
&Regret(\mathcal{M},\textbf{algo},K)\geq \frac{1}{18\sqrt{c_1 c_2}}\cdot \left[u\left(\left(1-\frac{2}{c_2}\right) H-\lambda^*\right)-u(-\lambda^*)\right]\sqrt{SAHK}
\end{align*}
for all $K\geq \frac{c_1 HSA}{2c_2}$, where the constants $c_1\geq 4,c_2>2$ and $\lambda^*$ satisfies 
\begin{align*}
1\in \left(1-\frac{2}{c_1}\right)\partial u\left(\left(1-\frac{2}{c_2}\right)H-\lambda^*\right)+\frac{2}{c_1}\partial u(-\lambda^*).
\end{align*}

(Main Properties of OCE)\label{L0}
For any utility function $u\in U_0$, and any bounded random variable $X$ the following properties hold:\\
(a)Shift Additivity. $OCE^u(X+c)=OCE^u(X)+c,\forall c\in \mathbb{R}$.\\
(b)Consistency. $OCE^u(c)=c$, for any constant $c\in \mathbb{R}$.\\
(c)Monotonicity. Let $Y$ be any random variable such that $X(w)\leq Y(w),\forall w\in \Omega$. Then,
\begin{align*}
OCE^u(X)\leq OCE^u(Y).
\end{align*}
(d)Concavity. For any random variables $X_1,X_2$ and any $\mu\in (0,1)$, we have
\begin{equation*}
OCE^u(\mu X_1+(1-\mu)X_2)\geq \mu OCE^u(X_1)+(1-\mu)OCE^u(X_2).
\end{equation*}

 Recall that $Q_h^{\pi}(s,a)=r_h(s,a)+OCE^{u}_{s'\sim P_h(\cdot\vert s,a)}(V^{\pi}_{h+1}(s'))$ and $V_{H+1}^{\pi}(s)=0,\forall s\in\mathcal{S}$. Then, we can calculate that
\begin{align*}
&Q_H^{\pi}(s,a)=r_H(s,a)+OCE^{u}_{s'\sim P_H(\cdot\vert s,a)}(V_{H+1}^{\pi}(s'))\overset{(1)}{=}r_H(s,a)\in [0,1],\\
&V_H^{\pi}(s)=\max_{a\in \mathcal{A}}r_H(s,a)\in [0,1],
\end{align*}
where equality (1) is due to property (b) in Lemma \ref{L0}. Hence, we have 
\begin{align*}
&Q_{H-1}^{\pi}(s,a)=r_{H-1}(s,a)+OCE^{u}_{s'\sim P_{H-1}(\cdot\vert s,a)}(V_{H}^{\pi}(s'))\overset{(1)}{\leq} r_{H-1}(s,a)+OCE^{u}_{s'\sim P_{H-1}(\cdot\vert s,a)}(1)\in [1,2],\\
&Q_{H-1}^{\pi}(s,a)=r_{H-1}(s,a)+OCE^{u}_{s'\sim P_{H-1}(\cdot\vert s,a)}(V_{H}^{\pi}(s'))\overset{(2)}{\geq} r_{H-1}(s,a)+OCE^{u}_{s'\sim P_{H-1}(\cdot\vert s,a)}(0)\in [0,1],\\
&V_{H-1}^{\pi}(s)=\max_{a\in \mathcal{A}}Q_{H-1}^{\pi}(s,a)\in [0,2],\\
\end{align*}
where inequalities (1) and (2) hold due to properties (b) and (c) in Lemma \ref{L0}. Carrying out this procedure repeatedly until step $h$, we can get 
\begin{align*}
Q_h^{\pi}(s,a)\in [0,H-h+1], \quad \text{and} \quad V_h^{\pi}(s)\in [0,H-h+1].
\end{align*}
Using the definition \eqref{eq:regret}, we then immediately obtain that 
$0\leq Regret(\mathcal{M},\textbf{algo},K)\leq KH$ for any \textbf{algo}.

