\label{L2}
For any probability measure $P_h(\cdot\vert s,a)$, any $s\in \mathcal{S},a\in\mathcal{A},h\in [H]$, suppose $V_{h+1}^{\pi}(s')\in [0,H-h]$ for $s'\sim P_h(\cdot\vert s,a)$. Then, we have 
\begin{equation}\label{S1}
OCE^{u}_{s'\sim P_h(\cdot\vert s,a)}(V_{h+1}^{\pi}(s'))=\max_{\lambda\in [0,H-h]}\{\lambda+E_{s'\sim P_h(\cdot\vert s,a)}[u(V_{h+1}^{\pi}(s')-\lambda)]\}.
\end{equation}

let 
\begin{equation}\label{HIST}
\mathbb{H}_h^k=((\mathcal{S}\times \mathcal{A})^{H-1}\times \mathcal{S})^{k-1}\times(\mathcal{S}\times\mathcal{A})^{h-1}\times\mathcal{S}
\end{equation}
be the set of possible histories up to step $h$ in episode $k$.

\label{L3}
For any $\delta\in (0,1)$, we have
\begin{equation}\label{S2}
\begin{aligned}
P\Bigg (& E_{s'\sim P_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]-E_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]\\
&\leq \left\vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\right\vert \sqrt{\frac{2\log(\frac{SAHK}{\delta})}{\max\{1,N^k_h(s,a)\}}},\\
&V_{h+1}^*:\mathcal{S}\to [0,H-h],\lambda_{h+1}^*\in [0,H-h],\forall (s,a,h,k)\in \mathcal{S}\times \mathcal{A}\times [H]\times [K]\Bigg)\geq 1-\delta.
\end{aligned}
\end{equation}

We adapt the proof of Lemma 7.3 in \cite{agarwal2019reinforcement} who consider the risk neural episodic RL setting. For each fixed $(s,a,h,k)\in \mathcal{S}\times\mathcal{A}\times [H]\times [K]$, we have to consider two cases.

Firstly, according to section \ref{SECALG}, when $N_h^k(s,a)=0$, we have $\hat{P}_h^k(s'\vert s,a)=0$ for all $s'\in\mathcal{S}$. According to Lemma \ref{L1} and Lemma \ref{L2}, $V^*_{h+1}(s^i_{h+1})\in [0,H-h]$ and $\lambda_{h+1}^*\in [0,H-h]$. Thus, we have $u(V_{h+1}^*(s_{h+1}^i)-\lambda_{h+1}^*)\in [u(-\lambda_{h+1}^*),u(H-h-\lambda_{h+1}^*)]$, where $u(-\lambda_{h+1}^*)\leq 0$ and $u(H-h-\lambda_{h+1}^*)\geq 0$. Then, we have
\begin{align*}
&E_{s'\sim P_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]-E_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]\\
&\overset{(1)}{=} E_{s'\sim P_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]\\
&\overset{(2)}{\leq} \vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\vert\\
&\overset{(3)}{\leq} \left\vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\right\vert \sqrt{\frac{2\log(\frac{SAHK}{\delta})}{\max\{1,N^k_h(s,a)\}}},
\end{align*}
where equality (1) holds because $\hat{P}_h^k(s'\vert s,a)=0$ for all $s'\in\mathcal{S}$, inequality (2) holds because $$u(V_{h+1}^*(s_{h+1}^i)-\lambda_{h+1}^*)\leq u(H-h-\lambda^*_{H+1})\leq \vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\vert,$$
and inequality (3) holds because $N_h^k(s,a)=0$ and $\log(\frac{SAHK}{\delta})>1$.
Therefore,
\begin{align*}
P\Bigg (& E_{s'\sim P_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]-E_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]\\
&\leq \left\vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\right\vert \sqrt{\frac{2\log(\frac{SAHK}{\delta})}{\max\{1,N^k_h(s,a)\}}},\\
&V_{h+1}^*:\mathcal{S}\to [0,H-h],\lambda_{h+1}^*\in [0,H-h]\Bigg)=1\geq 1-\frac{\delta}{SAHK}.
\end{align*}

Secondly, when $N_h^k(s,a)\geq 1$, by the definition of $\hat{P}_h^k$, we have
\begin{align*}
E_{s'\sim \hat{P}_h^k(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]=\frac{1}{N^k_h(s,a)}\sum_{i=1}^{k-1} 1_{\{(s_h^i,a_h^i)=(s,a)\}}u(V_{h+1}^*(s_{h+1}^i)-\lambda_{h+1}^*).
\end{align*}
Remark that when $N_h^k(s,a)\geq 1$, we have $k\geq 2$.

We define for $i=1, \ldots, k-1,$
\begin{align*}
X_i=E\left [1_{\{(s_h^i,a_h^i)=(s,a)\}}u(V_{h+1}^*(s_{h+1}^i)-\lambda_{h+1}^*)\Big\vert \mathcal{H}_h^i\right ]-1_{\{(s_h^i,a_h^i)=(s,a)\}}u(V_{h+1}^*(s_{h+1}^i)-\lambda_{h+1}^*).
\end{align*}
By the same argument as in the previous case, we conclude that $$u(V_{h+1}^*(s_{h+1}^i)-\lambda_{h+1}^*)\in [u(-\lambda_{h+1}^*),u(H-h-\lambda_{h+1}^*)].$$ Thus, we have $$u(-\lambda_{h+1}^*)-u(H-h-\lambda_{h+1}^*)\leq X_i\leq u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*).$$ In addition, it is evident that $E[X_i\vert \mathcal{H}_h^i]=0$, which implies that $(X_i)$ is a martingale difference sequence. 
Then, by Azuma-Hoeffding's inequality for martingales, with a probability of at least $1-\frac{\delta}{SAHK}$, we have
\begin{align*}
\sum_{i=1}^{k-1} X_i&=N_h^k(s,a)E_{s'\sim P_h(\cdot\vert s,a)}[u(V_{h+1}^*(s')-\lambda_{h+1}^*)]-\sum_{i=1}^{k-1} 1_{\{(s_h^i,a_h^i)=(s,a)\}}u(V_{h+1}^*(s_{h+1}^i)-\lambda_{h+1}^*)\\
&\leq \vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\vert \sqrt{2 N_h^k(s,a)\log(\frac{SAHK}{\delta})}
\end{align*}
Divided by $N_h^k(s,a)$ on both sides of the above inequality, combining the above two cases and using a union bound over all $(s,a,h,k)\in \mathcal{S}\times \mathcal{A}\times [H]\times [K]$, we obtain \eqref{S2}.

\begin{align*}
&E_{s'\sim P_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]-E_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]\\
&\overset{(1)}{=} E_{s'\sim P_h(\cdot\vert s,a)}\left [u(V_{h+1}^*(s')-\lambda_{h+1}^*)\right ]\\
&\overset{(2)}{\leq} \vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\vert\\
&\overset{(3)}{\leq} \left\vert u(H-h-\lambda_{h+1}^*)-u(-\lambda_{h+1}^*)\right\vert \sqrt{\frac{2\log(\frac{SAHK}{\delta})}{\max\{1,N^k_h(s,a)\}}},
\end{align*}

