\label{L5}
Conditional on the event $\mathcal{G}_1$, we have
$\hat{V}_h^k(s)\geq V^*_h(s)$ for any $k\in [K],s\in \mathcal{S}, h\in [H]$.

We prove the result by induction. 
Set $\hat{V}^k_{H+1}(s)=V^*_{H+1}(s)=0,\forall s\in \mathcal{S}$. Conditional on the occurrence of the event $\mathcal{G}_1$, assume $\hat{V}^{k}_{h+1}(s')\geq V^*_{h+1}(s'),\forall s'\in\mathcal{S}$. Then, under event $\mathcal{G}_1$, for step $h$, we have
\begin{align}
&b_h^k(s,a)+r_h(s,a)+OCE^{\phi}_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}(\hat{V}^k_{h+1}(s'))-r_h(s,a)-OCE^{\phi}_{s'\sim P_h(\cdot\vert s,a)}(V^*_{h+1}(s')) \nonumber \\
& \overset{(1)}{\geq} b_h^k(s,a)+OCE^{\phi}_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}(V^*_{h+1}(s'))-OCE^{\phi}_{s'\sim P_h(\cdot\vert s,a)}(V^*_{h+1}(s')) \nonumber \\
& \overset{(2)}{\geq} b_h^k(s,a)-\vert u(-H+h)\vert\sqrt{\frac{2\log\left (\frac{SAHK}{\delta}\right )}{\max\{1,N^k_h(s,a)\}}} \nonumber\\
& =0, \label{ineq:inter}
\end{align}
where inequality (1) follows from the assumption $\hat{V}^{k}_{h+1}(s')\geq V^*_{h+1}(s'),\forall s'\in\mathcal{S}$ and property (c) in Lemma \ref{L0}, and inequality (2) holds due to Lemma \ref{L4}. 
Recall that
\begin{align*}
&\hat{Q}_h^k(s,a)=\min\{b_h^k(s,a)+r_h(s,a)+OCE^{\phi}_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}(\hat{V}^k_{h+1}(s')),H-h+1\},\\
&Q_h^*(s,a)=r_h(s,a)+OCE^{\phi}_{s'\sim P_h(\cdot\vert s,a)}(V^*_{h+1}(s')). 
\end{align*}
By \eqref{ineq:inter} and Lemma~\ref{L1}, we can immediately obtain 

\begin{align*}
\hat{Q}_h^k(s,a)-Q^*_h(s,a)\geq 0.
\end{align*}
Because $\hat{V}_h^k(s)=\max_{a'\in\mathcal{A}}\hat{Q}^k_h(s,a')$, we have $\hat{V}_h^k(s)\geq V_h^*(s)$. The result then follows by induction.

\begin{align}
&b_h^k(s,a)+r_h(s,a)+OCE^{\phi}_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}(\hat{V}^k_{h+1}(s'))-r_h(s,a)-OCE^{\phi}_{s'\sim P_h(\cdot\vert s,a)}(V^*_{h+1}(s')) \nonumber \\
& \overset{(1)}{\geq} b_h^k(s,a)+OCE^{\phi}_{s'\sim \hat{P}^k_h(\cdot\vert s,a)}(V^*_{h+1}(s'))-OCE^{\phi}_{s'\sim P_h(\cdot\vert s,a)}(V^*_{h+1}(s')) \nonumber \\
