 We adapt the proof of Theorem 9 in \cite{domingues2021episodic} to our risk-sensitive setting. The proof of Theorem  \ref{THM3} is long, so we divide it into a few steps. 



\begin{itemize}
\item \textbf{Step 1: Constructing the hard MDP instances.}

We first construct hard MDP instances, which are almost the same as the ones in \cite{domingues2021episodic} except one small yet important difference: the transition probabilities in \eqref{eq:p}.  

Based on assumption \ref{ASSU2}, we can construct a full $A$-ary tree of depth $d-1$ with root $\tilde{s}_{root}$, which has $S-3$ states. In this rooted tree, each node has exactly $A$ children and the total number of nodes is given by $\sum_{i=0}^{d-1}A^i=S-3$. We add three special states to the tree: a ``waiting" state $\tilde{s}_w$ where the agent starts and can choose action $\tilde{a}_w$ to stay up to a stage $\bar{H}< H-d$, a ``good" state $\tilde{s}_g$ where the agent obtains rewards, and a ``bad" state $\tilde{s}_b$ that gives no reward. Note that $\bar{H}$ is a parameter to be chosen later. Both $\tilde{s}_g$ and $\tilde{s}_b$ are absorbing states. For any state in the tree, the transitions are deterministic, the $a$-th action in a node leads to the $a$-th child of that node. The agent stays or leaves $\tilde{s}_w$ with probability
\begin{equation*}
P_h(\tilde{s}_w\vert \tilde{s}_w,a):=1\{a=\tilde{a}_w,h\leq \bar{H}\},\ P_h(\tilde s_{root}\vert \tilde{s}_w,a):=1-P_h(\tilde{s}_w\vert \tilde{s}_w,a).
\end{equation*}
Then, the agent transverses the tree until she arrives at the leaves. Let $L$ be the number of leaves, and the set of the leaves is $\mathcal{L}=\{\tilde{s}_1,\cdots,\tilde{s}_L\}$. For any $\tilde{s}_i\in \mathcal{L}$, any action will lead to a transition to either $\tilde{s}_g$ or $\tilde{s}_b$ with the transition probability
\begin{equation} \label{eq:p}
P_h(\tilde{s}_g\vert \tilde{s}_i,a)=p+\Delta_{(h^*,s^*,a^*)}(h,\tilde{s}_i,a),\ P_h(\tilde{s}_b\vert \tilde{s}_i,a)=1-p-\Delta_{(h^*,s^*,a^*)}(h,\tilde{s}_i,a),
\end{equation}
where the parameter $p$ and the function $\Delta$ will be specified later. In \cite{domingues2021episodic}, $p$ is set to be $0.5$ in the risk-neutral setting, whereas we will tune $p$ in our risk-sensitive setting to obtain a tighter regret lower bound.  

The reward function is defined as 
\begin{equation*}
r_h(s,a):=1\{s=\tilde{s}_g,h\geq \bar{H}+d+1\},\ \forall a\in \mathcal{A} .
\end{equation*}
For each 
\begin{equation*}
(h^*,s^*,a^*)\in\{1+d,\cdots,\bar{H}+d\}\times\mathcal{L}\times\mathcal{A} =: \mathcal{Z},
\end{equation*}
we define an MDP $\mathcal{M}_{(h^*,s^*,a^*)}$, where $\Delta_{(h^*,s^*,a^*)}(h,\tilde{s}_i,a)=1\{h=h^*,\tilde{s}_i=s^*,a=a^*\}\epsilon$ and $\epsilon$ is a parameter to be chosen later. Denote by $P_{(h^*,s^*,a^*)}$ and $E_{(h^*,s^*,a^*)}$ the probability measure and expectation, respectively, in the MDP $\mathcal{M}_{(h^*,s^*,a^*)}$.
Let $\mathcal{M}_0$ be the MDP with $\Delta_0(h,\tilde{s}_i,a)=0$ for all $(h,\tilde{s}_i,a)\in [H]\times\mathcal{L}\times\mathcal{A}$. Denote by $P_0$ and $E_0$ the probability measure and expectation, respectively, in the MDP $\mathcal{M}_0$. 

\item  \textbf{Step 2: Computing the Expected Regret of an Algorithm in $\mathcal{M}_{(h^*,s^*,a^*)}$.}

We now compute
$Regret(\mathcal{M}_{(h^*,s^*,a^*)},\textbf{algo},K)$ for a learning algorithm \textbf{algo}, which executes policy $\pi^k$ in episode $k \in [K]$. By \eqref{eq:regret}, we need to compute the optimal value function, $V^*_1(s_1^k)$, and the value function under policy $\pi^k$, $V_1^{\pi^k}(s_1^k)$, for $k\in [K]$. 
Unlike \cite{domingues2021episodic}, these quantities can not be computed explicitly in general in our risk-sensitive setting because the OCE is defined by an optimization problem. Hence, in the following, we will bound $V_1^*(s_1^k)-V_1^{\pi^k}(s_1^k)$ in order to lower bound the regret. 




We first compute the value function $V_1^{\pi^k}(s_1^k)$ under policy $\pi^k$. For notational simplicity, we denote $\pi_h^k(s_h^k)$ as $a_h^k$ for all $h\in [H],k\in [K]$. Under policy $\pi^k$, we use $\hat{H}$ to denote the 
number of time steps in which the agent stays in the ``waiting" state, which is no larger than $\bar{H}$. Because there is no reward collected before step $\hat{H}+d$, we can obtain
\begin{align}\label{eq:V1pik}
V_1^{\pi^k}(s_1^k)=V_{\hat{H}+d}^{\pi^k}(s_{\hat{H}+d}^k).
\end{align}
Next, we compute $V_{\hat{H}+d}^{\pi^k}(s_{\hat{H}+d}^k).$ To this end, we first show 
\begin{align}\label{eq:VHd}
V_{\bar{H}+d+1}^{\pi^k}(s_{\bar{H}+d+1}^k)=(H-\bar{H}-d)\times 1\{s^k_{\bar{H}+d+1}=\tilde{s}_g\}.
\end{align}
We prove it by recursion. It is clear that 
\begin{align*}
V_{H}^{\pi^k}(s_{H}^k)&=r_H(s_{H}^k,a_{H}^k)+OCE_{s_{H+1}^k\sim P_H(\cdot\vert s_{H}^k,a_{H}^k)}(V_{H+1}^{\pi^k}(s_{H+1}^k))\overset{(1)}{=}1\{s_H^k=\tilde{s}_g\}\\
&\overset{(2)}{=}1\{s^k_{\bar{H}+d+1}=\tilde{s}_g\},
\end{align*}
where equality (1) holds because $V_{H+1}^{\pi^k}(s_{H+1}^k)=0$, and equality (2) follows from the fact that the agent is in the absorbing states when $h\geq \bar{H}+d+1$. Then, we can compute 
\begin{align*}
V_{H-1}^{\pi^k}(s_{H-1}^k)&=r_{H-1}(s_{H-1}^k,a_{H-1}^k)+OCE_{s^k_{H}\sim P_{H-1}(\cdot\vert s_{H-1}^k,a_{H-1}^k)}(V_{H}^{\pi^k}(s_{H}^k))\\
&\overset{(3)}{=}2\times 1\{s^k_{\bar{H}+d+1}=\tilde{s}_g\},
\end{align*}
where equality (3) holds because the random variable $1\{s^k_{\bar{H}+d+1}=\tilde{s}_g\}$ is known at step $H-1$, and we use property (b) in Lemma \ref{L0}. Repeating this procedure until time step $h=\bar{H}+d+1$, we obtain \eqref{eq:VHd}.  

Given \eqref{eq:VHd}, we next compute the value function under policy $\pi^k$ at time $\hat{H}+d+1$. Note that at time step $\hat{H}+d$, the agent is at the leaf of the rooted tree, where $\hat{H} \le \bar H.$ Hence, the probability that the agent is at good state $\tilde{s}_g$ at step $h=\hat{H}+d+1$ is the same as that at step $h=\bar{H}+d+1$. In addition, the reward function is given by $r_h(s,a)=1\{s=\tilde{s}_g,h\geq \bar{H}+d+1\},\forall a\in\mathcal{A}$. Hence, we obtain 
\begin{align*}
V_{\hat{H}+d+1}^{\pi^k}(s_{\hat{H}+d+1}^k)=V_{\bar{H}+d+1}^{\pi^k}(s_{\bar{H}+d+1}^k) 
&=(H-\bar{H}-d)\times 1\{s^k_{\bar{H}+d+1} 
=\tilde{s}_g\} \\
&=(H-\bar{H}-d)\times 1\{s^k_{\hat{H}+d+1}=\tilde{s}_g\}.
\end{align*}






It then follows that 
\begin{equation}\label{VLOW}
\begin{aligned}
&V_1^{\pi^k}(s_1^k) = V_{\hat{H}+d}^{\pi^k}(s_{\hat{H}+d}^k)\\
&=r_{\hat{H}+d}(s_{\hat{H}+d}^k,a_{\hat{H}+d}^k)+OCE_{s_{\hat{H}+d+1}^k\sim P_{\hat{H}+d}(\cdot\vert s_{\hat{H}+d}^k,a_{\hat{H}+d}^k)}(V_{\hat{H}+d+1}^{\pi^k}(s_{\hat{H}+d+1}^k))\\
&=OCE_{s_{\hat{H}+d+1}^k\sim P_{\hat{H}+d} (\cdot\vert s_{\hat{H}+d}^k,a_{\hat{H}+d}^k)}\left((H-\bar{H}-d)\times 1\{s^k_{\hat{H}+d+1}=\tilde{s}_g\}\right )\\
&=\sup_{\lambda\in [0,H-\bar{H}-d]}\{\lambda+P_{(h^*,s^*,a^*)}(s^k_{\hat{H}+d+1}=\tilde{s}_g)u(H-\bar{H}-d-\lambda)\\
&\quad \quad \quad \quad \quad \quad +(1-P_{(h^*,s^*,a^*)}(s^k_{\hat{H}+d+1}=\tilde{s}_g))u(-\lambda)\}\\
&=\sup_{\lambda\in [0,H-\bar{H}-d]}\{\lambda+P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g)u(H-\bar{H}-d-\lambda)\\
&\quad \quad \quad \quad \quad \quad +(1-P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g))u(-\lambda)\}.
\end{aligned}    
\end{equation}


Similar to Equation (7) in \cite{domingues2021episodic}, we can derive
