&P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g)\\
&= \sum_{h=1+d}^{\bar{H}+d}pP_{(h^*,s^*,a^*)}(s^k_{h}\in\mathcal{L})+1\{h=h^*\}P_{(h^*,s^*,a^*)}(s_h^k=s^*,a_h^k=a^*)\epsilon\\
&= p+\epsilon \cdot P_{(h^*,s^*,a^*)}(s_{h^*}^k=s^*,a_{h^*}^k=a^*).
\end{aligned}
\end{equation}
Together with \eqref{VLOW}, we obtain an expression of the value function $V_1^{\pi^k}(s_1^k)$.



We next compute the optimal value function $V_1^{*}(s_1^k)$. Based on \eqref{VLOW}, one can easily show that the optimal policy is to let $P_{(h^*,s^*,a^*)}(s_{h^*}^k=s^*,a_{h^*}^k=a^*)=1$. Specifically, in the MDP $\mathcal{M}_{(h^*,s^*,a^*)}$, the optimal policy is to traverse the tree at step $h^*-d$, so that the agent visits the leaf state $s^*$ at time step $h^*$ and takes the action $a^*$ at this leaf state. Thus, the optimal value function is given by
\begin{align*}
V_1^{*}(s_1^k)&=\sup_{\lambda\in [0,H-\bar{H}-d]}\{\lambda+(p+\epsilon)u(H-\bar{H}-d-\lambda)+(1-p-\epsilon)u(-\lambda)\}.
\end{align*}

Now, we can compute that for each episode $k\in [K]$,
\begin{align*}
&V_1^*(s_1^k)-V_1^{\pi^k}(s_1^k)\\
&=\sup_{\lambda\in [0,H-\bar{H}-d]}\{\lambda+(p+\epsilon)u(H-\bar{H}-d-\lambda)+(1-p-\epsilon)u(-\lambda)\}\\
&-\sup_{\lambda\in [0,H-\bar{H}-d]}\{\lambda+P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g)u(H-\bar{H}-d-\lambda)\\
&\quad \quad \quad \quad \quad \quad +(1-P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g))u(-\lambda)\}\\
&\overset{(1)}{\geq} \rho+(p+\epsilon)u(H-\bar{H}-d-\rho)+(1-p-\epsilon)u(-\rho)\\
&\quad -\rho-P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g)u(H-\bar{H}-d-\rho)-(1-P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g))u(-\rho)\\
&\overset{(2)}{=} \epsilon [u(H-\bar{H}-d-\rho)-u(-\rho)]\times [1-P_{(h^*,s^*,a^*)}(s_{h^*}^k=s^*,a_{h^*}^k=a^*)],
\end{align*}
where inequality $(1)$ holds by setting 
\begin{align}
\rho\in &\mathop{\arg\max}_{\lambda\in [0,H-\bar{H}-d]}\{\lambda+P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g)u(H-\bar{H}-d-\lambda)\nonumber\\
&\quad \quad \quad \quad \quad +(1-P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g))u(-\lambda)\},\label{eq:rho}
\end{align}
and equality $(2)$ holds by applying \eqref{S26}. 

Therefore, the regret of a learning algorithm \textbf{algo} in $\mathcal{M}_{(h^*,s^*,a^*)}$ can be lower bounded as follow: 
\begin{align} \label{eq:regret-lb}
&Regret(\mathcal{M}_{(h^*,s^*,a^*)},\textbf{algo},K) \nonumber \\
&= \sum_{k=1}^K E_{(h^*,s^*,a^*)} [V_1^*(s_1^k)-V_1^{\pi^k}(s_1^k)] \nonumber \\
&\geq  \epsilon [u(H-\bar{H}-d-\rho)-u(-\rho)]\sum_{k=1}^K\left (1-P_{(h^*,s^*,a^*)}(s_{h^*}^k=s^*,a_{h^*}^k=a^*) \right ) \nonumber \\
&=  \epsilon [u(H-\bar{H}-d-\rho)-u(-\rho)]\left (K-E_{(h^*,s^*,a^*)}\left[N^K_{(h^*,s^*,a^*)}\right]\right ),
\end{align}
where 
\begin{align}\label{eq:N-star}
N^K_{(h^*,s^*,a^*)}=\sum_{k=1}^K 1\{s_{h^*}=s^*,a_{h^*}=a^*\}.
\end{align}


\item \textbf{Step 3: Bounding Maximum Regret over all possible $\mathcal{M}_{(h^*,s^*,a^*)}$.}

We can deduce from \eqref{eq:regret-lb} that
the maximum regret of an algorithm \textbf{algo} over all possible  $\mathcal{M}_{(h^*,s^*,a^*)}$ is lower bounded by 
\begin{equation}\label{S20}
\begin{aligned}
&\mathop{\max}_{(h^*,s^*,a^*) \in \mathcal{Z}} Regret(\mathcal{M}_{(h^*,s^*,a^*)},\textbf{algo},K)\\
&\geq \frac{1}{\bar{H}LA}\sum_{(h^*,s^*,a^*) \in \mathcal{Z}}Regret(\mathcal{M}_{(h^*,s^*,a^*)},\textbf{algo},K)\\
&\geq  K[u(H-\bar{H}-d-\rho)-u(-\rho)]\epsilon \left (1-\frac{1}{K\bar{H}LA}\sum_{(h^*,s^*,a^*)} E_{(h^*,s^*,a^*)}\left[N^K_{(h^*,s^*,a^*)}\right]\right ).
\end{aligned}
\end{equation}
So to lower bound the regret, we have to upper bound $\sum_{(h^*,s^*,a^*) \in \mathcal{Z} }E_{(h^*,s^*,a^*)} \left[N^K_{(h^*,s^*,a^*)}\right]$.

\item \textbf{Step 4: Bounding $\sum_{(h^*,s^*,a^*) \in \mathcal{Z} }E_{(h^*,s^*,a^*)}\left[N^K_{(h^*,s^*,a^*)}\right]$.}

For this step, we use similar arguments to those used in \cite{domingues2021episodic}; see page 13 therein.
Fix $(h^*,s^*,a^*)\in [H]\times \mathcal{S}\times \mathcal{A}$. Because $\frac{1}{K}N_{(h^*,s^*,a^*)}^K\in [0,1]$, one can obtain from Lemma 1 of \cite{garivier2019explore} that 
\begin{align*}
kl\left (\frac{1}{K}E_0\left[N_{(h^*,s^*,a^*)}^K\right],\frac{1}{K}E_{(h^*,s^*,a^*)}\left[N_{(h^*,s^*,a^*)}^K\right]\right )\leq KL(P_0,P_{(h^*,s^*,a^*)}),
\end{align*}
where KL denotes the Kullback-Leibler divergence between two probability measures and $kl(p,q)$ denotes the KL divergence between two Bernoulli distributions with success probabilities $p$ and $q$ respectively; see Definition 4 in \cite{domingues2021episodic}. It then follows from Pinsker's inequality, $(p-q)^2\leq \frac{1}{2}kl(p,q)$, that 
\begin{align*}
\frac{1}{K}E_{(h^*,s^*,a^*)}\left[N_{(h^*,s^*,a^*)}^K\right]\leq \frac{1}{K}E_0\left[N_{(h^*,s^*,a^*)}^K\right]+\sqrt{\frac{1}{2}KL(P_{0},P_{(h^*,s^*,a^*)})}.
\end{align*}
Because $\mathcal{M}_0$ and $\mathcal{M}_{(h^*,s^*,a^*)}$ differ at stage $h^*$ when $(s_{h^*},a_{h^*})=(s^*,a^*)$, by Lemma 5 of \cite{domingues2021episodic} and Lemma \ref{L16} in Appendix~\ref{sec:aux}, we can prove that 
\begin{align*}
KL\left(P_{0},P_{(h^*,s^*,a^*)}\right)=E_0\left[N_{(h^*,s^*,a^*)}^K\right]kl(p,p+\epsilon)\leq E_0\left[N_{(h^*,s^*,a^*)}^K\right]\frac{c_1\epsilon^2}{p},
\end{align*}
where $c_1\geq 2$ is a certain positive constant, $p\in [0,1-\frac{1}{c_1}]$ and $\epsilon$ satisfies
\begin{align}\label{eq:eps-constraint}
\epsilon\in \left [0,\frac{(1-2p)+\sqrt{1-\frac{4p}{c_1}}}{2}\right ].
\end{align}

Thus, 
\begin{align*}
\frac{1}{K}E_{(h^*,s^*,a^*)}\left[N_{(h^*,s^*,a^*)}^K\right]\leq \frac{1}{K}E_0\left[N_{(h^*,s^*,a^*)}^K\right]+\sqrt{\frac{c_1}{2p}}\epsilon\sqrt{E_0\left[N_{(h^*,s^*,a^*)}^K\right]}.
\end{align*}
According to the definition of $N_{(h^*,s^*,a^*)}^K$ in \eqref{eq:N-star}, we know that $\mathop{\sum}_{(h^*,s^*,a^*) \in \mathcal{Z} }N_{(h^*,s^*,a^*)}^K\leq K$. Then, by Cauchy-Schwarz inequality, we have
\begin{align}\label{S21}
\frac{1}{K}\mathop{\sum}_{(h^*,s^*,a^*) \in \mathcal{Z} }E_{(h^*,s^*,a^*)}\left[N_{(h^*,s^*,a^*)}^K\right]\leq 1+\sqrt{\frac{c_1}{2p}}\epsilon\sqrt{\bar{H}LAK}.
\end{align}



\item \textbf{Step 5: Optimizing $\epsilon$ and Choosing $\bar{H}$ and $p$.}

By combining \eqref{S20} with \eqref{S21}, we have 
\begin{align}
&\mathop{\max}_{(h^*,s^*,a^*) \in \mathcal{Z} } Regret(\mathcal{M}_{(h^*,s^*,a^*)},\textbf{algo},K)\nonumber\\
&\geq K[u(H-\bar{H}-d-\rho)-u(-\rho)]\epsilon \left (1-\frac{1}{\bar{H}LA}-\sqrt{\frac{c_1}{2p}}\epsilon\frac{\sqrt{\bar{H}LAK}}{\bar{H}LA}\right ),\label{Q39}
\end{align}
where the right-hand side of the inequality is a quadratic function of $\epsilon$. Maximizing this function by taking 
\begin{align}\label{eq:eps-choice}
\epsilon=\sqrt{\frac{p}{2c_1}}\left(1-\frac{1}{\bar{H}LA}\right)\sqrt{\frac{\bar{H}LA}{K}},
\end{align}
we derive

\begin{align}
&\mathop{\max}_{(h^*,s^*,a^*) \in \mathcal{Z}} Regret(\mathcal{M}_{(h^*,s^*,a^*)},\textbf{algo},K)\nonumber\\
&\geq \frac{1}{2\sqrt{2}}\sqrt{\frac{p}{c_1}}[u(H-\bar{H}-d-\rho)-u(-\rho)]\sqrt{\bar{H}LAK}(1-\frac{1}{\bar{H}LA})^2.\label{Q40}
\end{align}
According to Assumption \ref{ASSU2}, we have $A\geq 2$, $S\geq 6$, and thus $L=(1-\frac{1}{A})(S-3)+\frac{1}{A}\geq \frac{S}{4}$. Then, we can deduce from \eqref{Q40} that
\begin{align}
&\mathop{\max}_{(h^*,s^*,a^*) \in \mathcal{Z} } Regret(\mathcal{M}_{(h^*,s^*,a^*)},\textbf{algo},K)\nonumber\\
&\geq \frac{1}{2\sqrt{2}}\cdot \sqrt{\frac{p}{c_1}}[u(H-\bar{H}-d-\rho)-u(-\rho)]\sqrt{\bar{H}\cdot\frac{S}{4}AK}\cdot \frac{4}{9}\nonumber\\
&= \frac{1}{9\sqrt{2}}\cdot \sqrt{\frac{p}{c_1}}[u(H-\bar{H}-d-\rho)-u(-\rho)]\sqrt{SA\bar{H}K}.\label{Q41}
\end{align}

The bound in \eqref{Q41} is not explicit in the sense that the quantity $\rho$ defined in \eqref{eq:rho} depends on the unknown probability $P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g)$, which equals $p+\epsilon \cdot P_{(h^*,s^*,a^*)}(s_{h^*}^k=s^*,a_{h^*}^k=a^*)$. We next lower bound the term on the right-hand-side of \eqref{Q41} in order to derive the explicit bound given in Theorem \ref{THM3}. 

Because $\rho$ satisfies \eqref{eq:rho}, by the first-order optimality condition, we have
\begin{align}\label{F38}
1\in P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g)\partial u(H-\bar{H}-d-\rho)+(1-P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g))\partial u(-\rho).
\end{align}
According to Assumption \ref{ASSU2}, we have $H\geq c_2 d$ with $c_2 >2$. We choose 
\begin{align}\label{eq:barH}
\bar H = \frac{H}{c_2}.
\end{align}
Then, by the monotonicity of the subgradients of the concave function $u$, we obtain from \eqref{F38} that
\begin{align}\label{F55}
1 \le P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g)\partial u\left( \left(1- \frac{2}{c_2}\right)H-\rho\right)+(1-P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g))\partial u(-\rho),
\end{align}
where the inequality means every element in the set on the right-hand-side is greater than one. Recall that  $P_{(h^*,s^*,a^*)}(s^k_{\bar{H}+d+1}=\tilde{s}_g) =p+\epsilon \cdot P_{(h^*,s^*,a^*)}(s_{h^*}^k=s^*,a_{h^*}^k=a^*)$. Then, we can deduce from \eqref{F38} that
\begin{align}\label{F38-2}
1 \le p \cdot \partial u\left( \left(1- \frac{2}{c_2}\right)H-\rho\right)+(1- p) \cdot \partial u(-\rho),
\end{align}
where we use the fact that $\partial u$ is monotone so that all
elements in the set $\partial u( (1- \frac{2}{c_2})H-\rho) - \partial u(-\rho)$ are all non-negative. Now consider the function $p \cdot \partial u( (1- \frac{2}{c_2})H-\lambda)+(1- p) \cdot \partial u(-\lambda)$ for $\lambda\in [0, \rho]$. When $\lambda=0$, it is clear that $ p \cdot \partial u( (1- \frac{2}{c_2})H)+(1- p) \cdot \partial u(0)$ contains an element that is smaller than one, because $1 \in \partial u(0)$ and the elements in $\partial u( (1- \frac{2}{c_2})H)$ are smaller than one. Together with \eqref{F38-2} and the continuity of the subdifferential mapping, we then deduce that 




there exists some $\lambda^* \in [0, \rho]$ such that
\begin{align}\label{eq:p-eq}
1 \in  p \cdot \partial u \left(\left(1-\frac{2}{c_2}\right)H-\lambda^*\right)+(1-p)\cdot \partial u(-\lambda^*).
\end{align}


Now, we are ready to lower bound the right-hand-side of \eqref{Q41}. Note that 
$ u(H-\bar{H}-d-\lambda) - u(-\lambda)$ is nondecreasing in $\lambda\in [0,H-\bar{H}-d]$. Using \eqref{eq:barH} and the assumption $H\geq 2c_2 d$,
we then have
\begin{align}
u(H-\bar{H}-d-\rho)-u(-\rho) \ge u \left(\left(1-\frac{2}{c_2}\right)H-\lambda^*\right) - u(-\lambda^*).  
\end{align}
For fixed $c_1 \ge 4$, we can choose 
\begin{align}
p = 1 - \frac{2}{c_1} \ge \frac{1}{2}.
\end{align}
It follows from \eqref{Q41} and \eqref{eq:barH} that 
\begin{align}
&\mathop{\max}_{(h^*,s^*,a^*) \in \mathcal{Z} } Regret(\mathcal{M}_{(h^*,s^*,a^*)},\textbf{algo},K)\nonumber\\
& \ge \frac{1}{9\sqrt{2}}\cdot \sqrt{\frac{p}{c_1}}[u(H-\bar{H}-d-\rho)-u(-\rho)]\sqrt{SA\bar{H}K} \nonumber \\
&\geq \frac{1}{18\sqrt{2c_1 c_2}}\cdot \left[u\left(\left(1-\frac{2}{c_2}\right) H-\lambda^*\right)-u(-\lambda^*)\right]\sqrt{SAHK}.
\end{align}
Finally, we need to make $\epsilon$ in \eqref{eq:eps-choice} satisfy the constraint \eqref{eq:eps-constraint}. It is easy to check that  $\epsilon \leq \sqrt{\frac{HSA}{2c_1 c_2 K}}$. Moreover, we have $\frac{(1-2p)+\sqrt{1-\frac{4p}{c_1}}}{2}\geq \frac{1}{c_1}$. Hence, we can choose $K\geq \frac{c_1 HSA}{2c_2}$ to make 
 $\epsilon$ in \eqref{eq:eps-choice} feasible. The proof is therefore completed. 








\end{itemize}

\label{L16}
Fix any constant $c_1\geq 2$. If $p\in [0,1-\frac{1}{c_1}]$ and $\epsilon\in \left [0,\frac{(1-2p)+\sqrt{1-\frac{4p}{c_1}}}{2}\right ]$, then we have 
$kl(p,p+\epsilon)\leq \frac{c_1 \epsilon^2}{p}$.

Using the inequality $\log(1+x)\leq x$ for any $x>-1$, we have
\begin{align*}
kl(p,p+\epsilon)&=p\log\left (\frac{p}{p+\epsilon}\right )+(1-p)\log\left (\frac{1-p}{1-p-\epsilon}\right )\\
&\leq p\left (\frac{p}{p+\epsilon}-1 \right )+(1-p)\left (\frac{1-p}{1-p-\epsilon}-1 \right )\\
&=\frac{\epsilon^2}{(p+\epsilon)(1-p-\epsilon)}\\
&\overset{(1)}{\leq} \frac{c_1\epsilon^2}{p},
\end{align*}
where inequality (1) holds if we have
\begin{align*}
\frac{p}{c_1}\leq p(1-p)+(1-2p)\epsilon-\epsilon^2.
\end{align*}
One can easily verify that the above inequality holds if $p\in [0,1-\frac{1}{c_1}]$ and $\epsilon\in \left [0,\frac{(1-2p)+\sqrt{1-\frac{4p}{c_1}}}{2}\right ]$. The proof is then completed.
